        void ScriptA4Hanako::a4_hanako() {
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A4_HANAKO);
            ks::SceneManager::set_script(SCRIPT_A4_HANAKO);
            IF_NOT_EXIT(ks::SceneManager::init_savedata(ks::progress));
            IF_NOT_EXIT(ks::SceneManager::set(ks::SceneManager("script_a4_hanako")));
        
            IF_NOT_EXIT(a4_hanako_truancy()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_faraway_presence()); // INLINE CALL
            if (!ks::progress.go_to_the_city) {
                ScriptA4Hanako::a4_hanako__condition_0_0();
            } 
            
        
            if (ks::progress.go_to_the_city && !ks::progress.agree_with_lilly) {
                ScriptA4Hanako::a4_hanako__condition_1_0();
            } 
            
        
            if (!ks::progress.go_to_the_city || !ks::progress.agree_with_lilly) {
                ScriptA4Hanako::a4_hanako__condition_2_0();
            } 
            
        
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_continuing_melody()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_shanghai_studiousness()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_his_past()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_city_rendezvous()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_whispered_touch()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_indeterminate_future()); // INLINE CALL
            IF_NOT_EXIT(a4_hanako_adulthood()); // INLINE CALL
        }
        void ScriptA4Hanako::a4_hanako_faraway_presence__menu_question_0() {
            bn::vector<ks::answer_ptr, 5> answers;
            if (true) answers.push_back({0, 1169});
            if (true) answers.push_back({1, 1170});
            IF_NOT_EXIT(ks::SceneManager::show_dialog_question(answers));
            const int answer = answers[ks::SceneManager::get_dialog_question_answer()].index;
            if (answer == 0) {
                ScriptA4Hanako::a4_hanako_faraway_presence__menu_question_0_agree_with_lilly();
            } else if (answer == 1) {
                ScriptA4Hanako::a4_hanako_faraway_presence__menu_question_0_trust_my_own_judgment();
            }
        }
        void ScriptA4Hanako::a4_hanako_faraway_presence__menu_question_0_agree_with_lilly() {
            ks::progress.agree_with_lilly = true;
        }
        void ScriptA4Hanako::a4_hanako_faraway_presence__menu_question_0_trust_my_own_judgment() {
            ks::progress.agree_with_lilly = false;
        }
